mapper.select:

where is_del = '0'

	AND contract_signed = #{contractSigned}


	AND status = #{status}


	AND carrier_type = #{carrierType}


	AND carrier_level = #{carrierLevel}


	AND (
		carrier_name like concat('%', #{keyword}, '%')
		or carrier_no like concat('%', #{keyword}, '%')
		or contact_name like concat('%', #{keyword}, '%')
		or contact_phone like concat('%', #{keyword}, '%')
	)


	AND create_time >= #{beginCreateTime}


	AND create_time <= #{endCreateTime}

order by create_time desc

